var fnGPUSupportsShaderFormats func(format_flags GPUShaderFormat, name *byte) bool

// Checks for GPU runtime support.
//
// Parameters:
//   - format_flags: a bitflag indicating which shader formats the app is able to provide.
//   - name: the preferred GPU driver, or NULL to let SDL pick the optimal driver.
//
// Returns: true if supported, false otherwise.
//
// Since: SDL 3.2.0.
//
// See also: CreateGPUDevice
//
// An empty name is passed as NULL.
func GPUSupportsShaderFormats(format_flags GPUShaderFormat, name string) bool {
	return fnGPUSupportsShaderFormats(format_flags, cstrNull(name))
}

var fnGPUSupportsProperties func(props PropertiesID) bool

// Checks for GPU runtime support.
//
// Parameters:
//   - props: the properties to use.
//
// Returns: true if supported, false otherwise.
//
// Since: SDL 3.2.0.
//
// See also: CreateGPUDeviceWithProperties
func GPUSupportsProperties(props PropertiesID) bool {
	return fnGPUSupportsProperties(props)
}

var fnCreateGPUDevice func(format_flags GPUShaderFormat, debug_mode bool, name *byte) *GPUDevice

// Creates a GPU context.
//
// The GPU driver name can be one of the following:
//
// - "vulkan": Vulkan
// - "direct3d12": D3D12
// - "metal": Metal
// - NULL: let SDL pick the optimal driver
//
// Parameters:
//   - format_flags: a bitflag indicating which shader formats the app is able to provide.
//   - debug_mode: enable debug mode properties and validations.
//   - name: the preferred GPU driver, or NULL to let SDL pick the optimal driver.
//
// Returns: a GPU context on success or NULL on failure; call GetError() for more information.
//
// Since: SDL 3.2.0.
//
// See also: CreateGPUDeviceWithProperties, GetGPUShaderFormats, GetGPUDeviceDriver, DestroyGPUDevice, GPUSupportsShaderFormats
//
// An empty name is passed as NULL.
func CreateGPUDevice(format_flags GPUShaderFormat, debug_mode bool, name string) *GPUDevice {
	return fnCreateGPUDevice(format_flags, debug_mode, cstrNull(name))
}

var fnCreateGPUDeviceWithProperties func(props PropertiesID) *GPUDevice

// Creates a GPU context.
//
// These are the supported properties:
//
//   - `PROP_GPU_DEVICE_CREATE_DEBUGMODE_BOOLEAN`: enable debug mode
//     properties and validations, defaults to true.
//   - `PROP_GPU_DEVICE_CREATE_PREFERLOWPOWER_BOOLEAN`: enable to prefer
//     energy efficiency over maximum GPU performance, defaults to false.
//   - `PROP_GPU_DEVICE_CREATE_VERBOSE_BOOLEAN`: enable to automatically log
//     useful debug information on device creation, defaults to true.
//   - `PROP_GPU_DEVICE_CREATE_NAME_STRING`: the name of the GPU driver to
//     use, if a specific one is desired.
//   - `PROP_GPU_DEVICE_CREATE_FEATURE_CLIP_DISTANCE_BOOLEAN`: Enable Vulkan
//     device feature shaderClipDistance. If disabled, clip distances are not
//     supported in shader code: gl_ClipDistance[] built-ins of GLSL,
//     SV_ClipDistance0/1 semantics of HLSL and [[clip_distance]] attribute of
//     Metal. Disabling optional features allows the application to run on some
//     older Android devices. Defaults to true.
//   - `PROP_GPU_DEVICE_CREATE_FEATURE_DEPTH_CLAMPING_BOOLEAN`: Enable
//     Vulkan device feature depthClamp. If disabled, there is no depth clamp
//     support and enable_depth_clip in GPURasterizerState must always be
//     set to true. Disabling optional features allows the application to run on
//     some older Android devices. Defaults to true.
//   - `PROP_GPU_DEVICE_CREATE_FEATURE_INDIRECT_DRAW_FIRST_INSTANCE_BOOLEAN`:
//     Enable Vulkan device feature drawIndirectFirstInstance. If disabled, the
//     argument first_instance of GPUIndirectDrawCommand must be set to
//     zero. Disabling optional features allows the application to run on some
//     older Android devices. Defaults to true.
//   - `PROP_GPU_DEVICE_CREATE_FEATURE_ANISOTROPY_BOOLEAN`: Enable Vulkan
//     device feature samplerAnisotropy. If disabled, enable_anisotropy of
//     GPUSamplerCreateInfo must be set to false. Disabling optional
//     features allows the application to run on some older Android devices.
//     Defaults to true.
//
// These are the current shader format properties:
//
//   - `PROP_GPU_DEVICE_CREATE_SHADERS_PRIVATE_BOOLEAN`: The app is able to
//     provide shaders for an NDA platform.
//   - `PROP_GPU_DEVICE_CREATE_SHADERS_SPIRV_BOOLEAN`: The app is able to
//     provide SPIR-V shaders if applicable.
//   - `PROP_GPU_DEVICE_CREATE_SHADERS_DXBC_BOOLEAN`: The app is able to
//     provide DXBC shaders if applicable
//   - `PROP_GPU_DEVICE_CREATE_SHADERS_DXIL_BOOLEAN`: The app is able to
//     provide DXIL shaders if applicable.
//   - `PROP_GPU_DEVICE_CREATE_SHADERS_MSL_BOOLEAN`: The app is able to
//     provide MSL shaders if applicable.
//   - `PROP_GPU_DEVICE_CREATE_SHADERS_METALLIB_BOOLEAN`: The app is able to
//     provide Metal shader libraries if applicable.
//
// With the D3D12 backend:
//
//   - `PROP_GPU_DEVICE_CREATE_D3D12_SEMANTIC_NAME_STRING`: the prefix to
//     use for all vertex semantics, default is "TEXCOORD".
//   - `PROP_GPU_DEVICE_CREATE_D3D12_ALLOW_FEWER_RESOURCE_SLOTS_BOOLEAN`: By
//     default, Resourcing Binding Tier 2 is required for D3D12 support.
//     However, an application can set this property to true to enable Tier 1
//     support, if (and only if) the application uses 8 or fewer storage
//     resources across all shader stages. As of writing, this property is
//     useful for targeting Intel Haswell and Broadwell GPUs; other hardware
//     either supports Tier 2 Resource Binding or does not support D3D12 in any
//     capacity. Defaults to false.
//   - `PROP_GPU_DEVICE_CREATE_D3D12_AGILITY_SDK_VERSION_NUMBER`: Certain
//     feature checks are only possible on Windows 11 by default. By setting
//     this alongside `PROP_GPU_DEVICE_CREATE_D3D12_AGILITY_SDK_PATH_STRING`
//     and vendoring D3D12Core.dll from the D3D12 Agility SDK, you can make
//     those feature checks possible on older platforms. The version you provide
//     must match the one given in the DLL.
//   - `PROP_GPU_DEVICE_CREATE_D3D12_AGILITY_SDK_PATH_STRING`: Certain
//     feature checks are only possible on Windows 11 by default. By setting
//     this alongside
//     `PROP_GPU_DEVICE_CREATE_D3D12_AGILITY_SDK_VERSION_NUMBER` and
//     vendoring D3D12Core.dll from the D3D12 Agility SDK, you can make those
//     feature checks possible on older platforms. The path you provide must be
//     relative to the executable path of your app. Be sure not to put the DLL
//     in the same directory as the exe; Microsoft strongly advises against
//     this!
//
// With the Vulkan backend:
//
//   - `PROP_GPU_DEVICE_CREATE_VULKAN_REQUIRE_HARDWARE_ACCELERATION_BOOLEAN`:
//     By default, Vulkan device enumeration includes drivers of all types,
//     including software renderers (for example, the Lavapipe Mesa driver).
//     This can be useful if your application _requires_ `SDL_GPU`, but if you can
//     provide your own fallback renderer (for example, an OpenGL renderer) this
//     property can be set to true. Defaults to false.
//   - `PROP_GPU_DEVICE_CREATE_VULKAN_OPTIONS_POINTER`: a pointer to an
//     GPUVulkanOptions structure to be processed during device creation.
//     This allows configuring a variety of Vulkan-specific options such as
//     increasing the API version and opting into extensions aside from the
//     minimal set SDL requires.
//
// With the Metal backend: -
// `PROP_GPU_DEVICE_CREATE_METAL_ALLOW_MACFAMILY1_BOOLEAN`: By default,
// macOS support requires what Apple calls "MTLGPUFamilyMac2" hardware or
// newer. However, an application can set this property to true to enable
// support for "MTLGPUFamilyMac1" hardware, if (and only if) the application
// does not write to sRGB textures. (For history's sake: MacFamily1 also does
// not support indirect command buffers, MSAA depth resolve, and stencil
// resolve/feedback, but these are not exposed features in `SDL_GPU`.)
//
// Parameters:
//   - props: the properties to use.
//
// Returns: a GPU context on success or NULL on failure; call GetError() for more information.
//
// Since: SDL 3.2.0.
//
// See also: GetGPUShaderFormats, GetGPUDeviceDriver, DestroyGPUDevice, GPUSupportsProperties
func CreateGPUDeviceWithProperties(props PropertiesID) *GPUDevice {
	return fnCreateGPUDeviceWithProperties(props)
}

