var fnCreateGPUShader func(device *GPUDevice, createinfo *GPUShaderCreateInfo) *GPUShader

// Creates a shader to be used when creating a graphics pipeline.
//
// Shader resource bindings must be authored to follow a particular order
// depending on the shader format.
//
// For SPIR-V shaders, use the following resource sets:
//
// For vertex shaders:
//
//   - 0: Sampled textures, followed by storage textures, followed by storage
//     buffers
//   - 1: Uniform buffers
//
// For fragment shaders:
//
//   - 2: Sampled textures, followed by storage textures, followed by storage
//     buffers
//   - 3: Uniform buffers
//
// For DXBC and DXIL shaders, use the following register order:
//
// For vertex shaders:
//
//   - (t[n], space0): Sampled textures, followed by storage textures, followed
//     by storage buffers
//   - (s[n], space0): Samplers with indices corresponding to the sampled
//     textures
//   - (b[n], space1): Uniform buffers
//
// For pixel shaders:
//
//   - (t[n], space2): Sampled textures, followed by storage textures, followed
//     by storage buffers
//   - (s[n], space2): Samplers with indices corresponding to the sampled
//     textures
//   - (b[n], space3): Uniform buffers
//
// For MSL/metallib, use the following order:
//
//   - [[texture]]: Sampled textures, followed by storage textures
//   - [[sampler]]: Samplers with indices corresponding to the sampled textures
//   - [[buffer]]: Uniform buffers, followed by storage buffers. Vertex buffer 0
//     is bound at [[buffer(14)]], vertex buffer 1 at [[buffer(15)]], and so on.
//     Rather than manually authoring vertex buffer indices, use the
//     [[stage_in]] attribute which will automatically use the vertex input
//     information from the GPUGraphicsPipeline.
//
// Shader semantics other than system-value semantics do not matter in D3D12
// and for ease of use the SDL implementation assumes that non system-value
// semantics will all be TEXCOORD. If you are using HLSL as the shader source
// language, your vertex semantics should start at TEXCOORD0 and increment
// like so: TEXCOORD1, TEXCOORD2, etc. If you wish to change the semantic
// prefix to something other than TEXCOORD you can use
// PROP_GPU_DEVICE_CREATE_D3D12_SEMANTIC_NAME_STRING with
// CreateGPUDeviceWithProperties().
//
// There are optional properties that can be provided through `props`. These
// are the supported properties:
//
//   - `PROP_GPU_SHADER_CREATE_NAME_STRING`: a name that can be displayed in
//     debugging tools.
//
// Parameters:
//   - device: a GPU Context.
//   - createinfo: a struct describing the state of the shader to create.
//
// Returns: a shader object on success, or NULL on failure; call GetError() for more information.
//
// Since: SDL 3.2.0.
//
// See also: CreateGPUGraphicsPipeline, ReleaseGPUShader
func CreateGPUShader(device *GPUDevice, createinfo *GPUShaderCreateInfo) *GPUShader {
	return fnCreateGPUShader(device, createinfo)
}

var fnCreateGPUTexture func(device *GPUDevice, createinfo *GPUTextureCreateInfo) *GPUTexture

// Creates a texture object to be used in graphics or compute workflows.
//
// The contents of this texture are undefined until data is written to the
// texture, either via UploadToGPUTexture or by performing a render or
// compute pass with this texture as a target.
//
// Note that certain combinations of usage flags are invalid. For example, a
// texture cannot have both the SAMPLER and GRAPHICS_STORAGE_READ flags.
//
// If you request a sample count higher than the hardware supports, the
// implementation will automatically fall back to the highest available sample
// count.
//
// There are optional properties that can be provided through
// GPUTextureCreateInfo's `props`. These are the supported properties:
//
//   - `PROP_GPU_TEXTURE_CREATE_D3D12_CLEAR_R_FLOAT`: (Direct3D 12 only) if
//     the texture usage is GPU_TEXTUREUSAGE_COLOR_TARGET, clear the texture
//     to a color with this red intensity. Defaults to zero.
//   - `PROP_GPU_TEXTURE_CREATE_D3D12_CLEAR_G_FLOAT`: (Direct3D 12 only) if
//     the texture usage is GPU_TEXTUREUSAGE_COLOR_TARGET, clear the texture
//     to a color with this green intensity. Defaults to zero.
//   - `PROP_GPU_TEXTURE_CREATE_D3D12_CLEAR_B_FLOAT`: (Direct3D 12 only) if
//     the texture usage is GPU_TEXTUREUSAGE_COLOR_TARGET, clear the texture
//     to a color with this blue intensity. Defaults to zero.
//   - `PROP_GPU_TEXTURE_CREATE_D3D12_CLEAR_A_FLOAT`: (Direct3D 12 only) if
//     the texture usage is GPU_TEXTUREUSAGE_COLOR_TARGET, clear the texture
//     to a color with this alpha intensity. Defaults to zero.
//   - `PROP_GPU_TEXTURE_CREATE_D3D12_CLEAR_DEPTH_FLOAT`: (Direct3D 12 only)
//     if the texture usage is GPU_TEXTUREUSAGE_DEPTH_STENCIL_TARGET, clear
//     the texture to a depth of this value. Defaults to zero.
//   - `PROP_GPU_TEXTURE_CREATE_D3D12_CLEAR_STENCIL_NUMBER`: (Direct3D 12
//     only) if the texture usage is GPU_TEXTUREUSAGE_DEPTH_STENCIL_TARGET,
//     clear the texture to a stencil of this Uint8 value. Defaults to zero.
//   - `PROP_GPU_TEXTURE_CREATE_NAME_STRING`: a name that can be displayed
//     in debugging tools.
//
// Parameters:
//   - device: a GPU Context.
//   - createinfo: a struct describing the state of the texture to create.
//
// Returns: a texture object on success, or NULL on failure; call GetError() for more information.
//
// Since: SDL 3.2.0.
//
// See also: UploadToGPUTexture, DownloadFromGPUTexture, BeginGPURenderPass, BeginGPUComputePass, BindGPUVertexSamplers, BindGPUVertexStorageTextures, BindGPUFragmentSamplers, BindGPUFragmentStorageTextures, BindGPUComputeStorageTextures, BlitGPUTexture, ReleaseGPUTexture, GPUTextureSupportsFormat
func CreateGPUTexture(device *GPUDevice, createinfo *GPUTextureCreateInfo) *GPUTexture {
	return fnCreateGPUTexture(device, createinfo)
}

